// Recomputes Template Route + Email 2 Route from data ALREADY in the sheet.
// No Apify, no Claude, no cost. Route depends only on Priority, Competitor
// Reviews, Review Count, Top Complaint and Best Review Quote - all stored - so
// when the ROUTING RULE changes (Levers 3 & 4), existing rows can be upgraded
// without re-enriching anything.
//
// Writes ONLY the two route columns, so it cannot touch the Claude fields and is
// immune to HAZARD-1.
try {
  var apply = false;
  try { apply = ($('Run').first().json.body || {}).apply === true; } catch (eA) { }

  var values = ($input.first().json || {}).values || [];
  if (values.length < 2) { return [{ json: { error: 'Sheet read returned no rows' } }]; }
  var H = values[0], I = {};
  for (var h = 0; h < H.length; h++) { I[String(H[h]).trim()] = h; }
  function c(r, n) { var i = I[n]; if (i === undefined) { return ''; } var x = r[i]; return (x === undefined || x === null) ? '' : String(x).trim(); }
  function N(r, n) { var x = c(r, n); if (x === '') { return 0; } var y = Number(x); return isNaN(y) ? 0 : y; }
  function B(x) { var s = String(x).toLowerCase(); return s === 'true' || s === 'yes' || s === '1'; }

  // Kept in lockstep with '📋 Build CRM Row' in the CHILD workflow.
  var KW = ['call','phone','response','respons','unrespon','respond','reply','answer','rang','reach','voicemail','contact','get back','get hold','get through','pickup','pick up','available','message','communic','follow','appointment','schedul','no-show','no show','turn up','turned up','show up','showed up','never came','never turned','chase','chasing','ignore','missed'];
  function isCall(x) { if (!x) { return false; } var s = String(x).toLowerCase(); for (var i = 0; i < KW.length; i++) { if (s.indexOf(KW[i]) !== -1) { return true; } } return false; }
  function route1(p, cr, rc, tc, bq) {
    var gap = cr - rc;
    if ((p === '1' && gap >= 10) || gap >= 30) {
      if (tc && isCall(tc)) { return 'A'; }
      if (bq) { return 'A-v2'; }
      return 'A-lite';
    }
    if (tc && isCall(tc)) { return 'B'; }
    return 'D';
  }
  function route2(r, hg, cw, ct) {
    if (r === 'A' || r === 'A-v2' || r === 'A-lite') { if (hg && cw && ct) { return 'E1'; } return 'E2'; }
    return 'E3';
  }

  var tIdx = I['Template Route'], uIdx = I['Email 2 Route'];
  if (tIdx === undefined || uIdx === undefined) { return [{ json: { error: 'route columns not found' } }]; }
  if (uIdx !== tIdx + 1) { return [{ json: { error: 'Template Route and Email 2 Route are not adjacent - aborting rather than writing the wrong columns' } }]; }
  function colLetter(n) { var s = ''; var x = n + 1; while (x > 0) { var m = (x - 1) % 26; s = String.fromCharCode(65 + m) + s; x = Math.floor((x - 1) / 26); } return s; }

  var rows = values.slice(1);
  var out = [], changed = 0, changed2 = 0, byPair = {}, samples = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    var oldR = c(row, 'Template Route'), oldR2 = c(row, 'Email 2 Route');
    var nr = route1(c(row, 'Priority'), N(row, 'Competitor Reviews'), N(row, 'Review Count'), c(row, 'Top Complaint'), c(row, 'Best Review Quote'));
    var nr2 = route2(nr, B(c(row, 'Hours Gap')), B(c(row, 'Competitor Has Weekend')), c(row, 'Closing Time'));
    if (nr !== oldR) {
      changed++;
      var k = (oldR || '(blank)') + ' -> ' + nr;
      byPair[k] = (byPair[k] || 0) + 1;
      if (samples.length < 5) { samples.push({ row: i + 2, company: c(row, 'Company Name'), from: oldR, to: nr, priority: c(row, 'Priority'), gap: N(row, 'Competitor Reviews') - N(row, 'Review Count') }); }
    }
    if (nr2 !== oldR2) { changed2++; }
    out.push([nr, nr2]);
  }

  return [{ json: {
    apply: apply,
    mode: apply ? 'APPLY - will write to the sheet' : 'DRY RUN - nothing written. POST {"apply":true} to commit.',
    rowsProcessed: rows.length,
    templateRouteChanges: changed,
    email2RouteChanges: changed2,
    byTransition: byPair,
    samples: samples,
    _range: "'Outreach CRM'!" + colLetter(tIdx) + '2:' + colLetter(uIdx) + (rows.length + 1),
    _values: out
  }}];
} catch (e) { return [{ json: { error: 'Compute failed: ' + e.message } }]; }

// Strips the bulky _values payload out of the response and reports the outcome.
try {
  var comp = $('Compute Routes').first().json;
  var written = null;
  try {
    var w = $('Write Routes').first().json;
    if (w && w.updatedCells !== undefined) { written = { updatedRange: w.updatedRange, updatedRows: w.updatedRows, updatedCells: w.updatedCells }; }
    else if (w && w.error) { written = { error: w.error }; }
  } catch (e) { }

  return [{ json: {
    mode: comp.mode,
    rowsProcessed: comp.rowsProcessed,
    templateRouteChanges: comp.templateRouteChanges,
    email2RouteChanges: comp.email2RouteChanges,
    byTransition: comp.byTransition,
    samples: comp.samples,
    targetRange: comp._range,
    sheetWrite: written || 'not attempted (dry run)',
    error: comp.error || null
  }}];
} catch (e) { return [{ json: { error: 'Report failed: ' + e.message } }]; }
